#!/usr/bin/env python3
# Generated by build.py; maintain frontend.py and the original converter engines.
# Deploy this single script: all three trusted engine sources are embedded below.
# No sibling scripts, downloads or third-party packages are required.
"""Convert supported Elegant, ASTRA or legacy OPAL inputs into OPALX candidates.

Python 3.9+, standard library only. Offline: no installation or tracking.
The deployable toOPALX.py embeds the three tested conversion engines.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import posixpath
import shutil
import sys
import tempfile
import textwrap
import types

