class ConversionFailure(ValueError):
    """A refused candidate, optionally carrying its original engine diagnostics."""

    def __init__(self, message, report=None):
        super().__init__(message)
        self.report = report


class _HelpFormatter(argparse.RawDescriptionHelpFormatter,
                     argparse.ArgumentDefaultsHelpFormatter):
    pass


def load_engine(mode):
    """Load only bundled, hash-checked trusted code in an isolated namespace."""
    if mode not in MODES:
        raise ValueError('Unknown conversion mode: ' + str(mode))
    if mode not in _ENGINE_CACHE:
        source = _ENGINE_SOURCES[mode]
        if hashlib.sha256(source.encode('utf-8')).hexdigest() != _ENGINE_HASHES[mode]:
            raise ValueError('Bundled engine fingerprint mismatch: ' + mode)
        name = '_toOPALX_' + mode + '_' + _ENGINE_HASHES[mode][:12]
        module = types.ModuleType(name)
        module.__file__ = str(Path(__file__).resolve())
        sys.modules[name] = module
        try:
            exec(compile(source, '<bundled ' + mode + ' converter>', 'exec'), module.__dict__)
        except Exception:
            sys.modules.pop(name, None)
            raise
        _ENGINE_CACHE[mode] = module
    return _ENGINE_CACHE[mode]


def build_parser(mode=None, *, more=False):
    """Expose the selected mode's contract and only its applicable controls."""
    if mode is not None and mode not in MODES:
        raise ValueError('Unknown conversion mode: ' + str(mode))
    description = __doc__.strip()
    scope = SCOPES[mode] if mode else '\n'.join(
        ('Modes: elegant, astra, opal.',
         'Use --help --mode elegant (or astra/opal) for expected inputs, supported',
         'physics, limitations and that mode\'s conversion controls.'))
    if more:
        scope += '\n\n' + '\n\n'.join(ELEMENT_HELP[item] for item in ((mode,) if mode else MODES))
    parser = argparse.ArgumentParser(prog='toOPALX.py', description=description,
        epilog=scope + '\n\n' + OUTPUT_HELP, formatter_class=_HelpFormatter)
    parser.add_argument('--version', action='version', version='toOPALX ' + VERSION)
    parser.add_argument('--more', action='store_true', help='With --help, list available elements and their restrictions')
    parser.add_argument('--mode', choices=MODES, required=True, help='Source input format')
    parser.add_argument('--infile', type=Path, required=True, help='Source entry input file')
    parser.add_argument('--outfile', type=Path, help='New OPALX entry file ending in .in')
    parser.add_argument('--inspect', action='store_true', help='Inspect supported source structure; write nothing')
    parser.add_argument('--json', action='store_true', dest='json_output',
                        help='Print the full conversion report as JSON instead of the concise terminal summary')
    if mode == 'elegant':
        parser.add_argument('--charge-c', type=float, dest='charge_C', help='Explicit positive bunch-charge magnitude [C]')
        parser.add_argument('--dt', type=float, default=1e-12, dest='dt_s', help='Target timestep [s]')
        parser.add_argument('--max-steps', type=int, default=100000, help='Target tracking step budget')
        parser.add_argument('--particle-dump-frequency', type=int, default=100000000, dest='dump_frequency', help='Particle-output step interval')
        parser.add_argument('--statistics-frequency', type=int, default=100, dest='stat_frequency', help='Statistics-output step interval')
        parser.add_argument('--source-rest-energy-ev', type=float, default=510999.06, dest='source_rest_energy_eV', help='Audited source electron rest energy [eV]')
    elif mode == 'astra':
        for flag, default, explanation in (
            ('rf-subdivisions', 4, 'RF longitudinal subdivisions'),
            ('map-radius', .05, 'First-order RF radial support [m]'),
            ('fourier-terms', 128, 'RF Fourier terms'),
            ('quad-dz', .00025, 'Maximum quadrupole z grid spacing [m]'),
            ('quad-radius', .05, 'Quadrupole transverse halfwidth [m]'),
            ('dipole-dz', .00025, 'Maximum dipole z grid spacing [m]'),
            ('dipole-dx', .0005, 'Maximum dipole bend-coordinate grid spacing [m]'),
            ('dipole-radius', .05, 'Dipole global x/y halfwidth [m]'),
            ('dipole-reference-ds', .00025, 'Dipole reference arc integration step [m]'),
            ('particle-dump-frequency', 100000000, 'Particle-output step interval')):
            parser.add_argument('--' + flag, type=int if isinstance(default, int) else float,
                                default=default, help=explanation)
        parser.add_argument('--center-launch-frame', action='store_true', help='Explicitly translate launch and RF/solenoid poses to the centroid frame')
    return parser


def inspect(mode, infile, **options):
    """Inspect without writing, preserving each backend's structural assessment."""
    source = Path(infile).expanduser().resolve()
    engine = load_engine(mode)
    if mode == 'elegant':
        backend = engine.inspect_source(source,
            source_rest_energy_eV=options.get('source_rest_energy_eV', engine.SOURCE_REST_EV),
            replace_unavailable=True)
    elif mode == 'astra':
        groups, policy = engine.conversion_groups(
            engine.parse_namelists(source.read_text(encoding='utf-8-sig')),
            force_no_space_charge=True)
        backend = engine.assess(groups)
        backend['fieldsolver_policy'] = policy
    else:
        backend = engine.process(source, replace_unavailable=True)
    return {'tool': 'toOPALX', 'version': VERSION, 'mode': mode,
            'backend_version': _ENGINE_VERSIONS[mode], 'infile': str(source),
            'status': backend['status'], 'physics_validated': False, 'backend_report': backend,
            **_policy_report(mode, backend)}


def _policy_report(mode, backend):
    """Expose removed elements and the mandatory solver policy in every report."""
    policy = backend.get('fieldsolver_policy')
    if policy is None:
        policy = ({'target_type': 'source-defined', 'forced_off': False,
                   'reason': 'OPAL fieldsolver settings are preserved'} if mode == 'opal'
                  else {'target_type': 'NONE', 'forced_off': True,
                        'reason': 'Non-OPAL conversions disable space charge'})
    return {'unavailable_elements': backend.get('unavailable_elements', []),
            'removed_constructs': backend.get('removed_constructs', []),
            'model_approximations': backend.get('model_approximations', []),
            'asset_migrations': backend.get('asset_migrations', []),
            'placement_warnings': [item['reason'] for file in backend.get('files', [])
                                   for item in file.get('changes', [])
                                   if item.get('rule') == 'legacy-cyclotron-sectors'],
            'fieldsolver_policy': policy}


def conversion_summary(report):
    """Frame every drift replacement in a visible, 80-column terminal box."""
    elements = report['unavailable_elements']
    lines = ['Unavailable elements replaced with DRIFT: ' + str(len(elements))]
    for element in elements:
        length = element.get('length_m', element.get('length'))
        source_file = report.get('backend_report', {}).get('lattice_file', report['infile'])
        location = element.get('file', source_file)
        if 'line' in element:
            location += ':' + str(element['line'])
        if 'occurrence' in element:
            location += ', occurrence ' + str(element['occurrence'])
        lines.append('  ' + element['name'] + ' (' + element['source_type']
                     + ') -> DRIFT, L=' + str(length) + ' m [' + location + ']')
        if element.get('length_origin'):
            lines.append('    '+element['reason'])
    if not elements:
        lines.append('  None.')
    removed = report.get('removed_constructs', [])
    if removed:
        lines.append('')
        lines.append('Obsolete constructs removed: '+str(len(removed)))
        for item in removed:
            label = item.get('kind', item.get('rule', 'obsolete construct'))
            if item.get('name'):
                label = item['name']+' ('+label+')'
            if item.get('attribute'):
                label += '.'+item['attribute']
            location = item.get('file', report['infile'])
            if item.get('line'):
                location += ':'+str(item['line'])
            lines.append('  '+label+' ['+location+']')
    approximations = report.get('model_approximations', [])
    if approximations:
        lines.append('')
        lines.append('Model approximations: '+str(len(approximations)))
        for item in approximations:
            location = item.get('file', report['infile'])
            if item.get('line'):
                location += ':'+str(item['line'])
            lines.append('  '+str(item.get('name') or item['kind'])+': '
                         +item['source_type']+' -> '+item['target_type']
                         +' (APPROXIMATION) ['+location+']')
            if item.get('discarded_attributes'):
                lines.append('    Dropped shape parameters: '+', '.join(sorted(item['discarded_attributes'])))
            lines.append('    '+item['reason'])
    if report['mode'] != 'opal':
        lines.append('Fieldsolver: NONE (space charge off).')
    asset_changes = report.get('asset_migrations', [])
    if asset_changes:
        lines.append('')
        lines.append('Particle-file migrations: '+str(len(asset_changes)))
        for item in asset_changes:
            lines.append('  '+item['file']+': inserted '+' '.join(item['columns'])+' header')
            lines.append('    '+item['reason'])
    for warning in report.get('placement_warnings', []):
        lines.extend(['', warning])
    framed = ['*' * 80]
    for line in lines:
        for row in textwrap.wrap(line, width=76, subsequent_indent='    ',
                                 break_on_hyphens=False) or ['']:
            framed.append('* ' + row.ljust(76) + ' *')
    framed.append('*' * 80)
    return '\n'.join(framed)


def relocate(text, asset_prefix, known_files):
    """Edit literal OPAL dependency value spans; all paths use the entry cwd."""
    if (not isinstance(asset_prefix, str) or not asset_prefix or asset_prefix in ('.', '..')
            or any(c in asset_prefix for c in '/\\\"\'\r\n\x00')):
        raise ValueError('Asset prefix must be one portable relative directory name')
    engine = load_engine('opal')
    edits, changes = [], []
    for tokens in engine.statements(text):
        statement = engine.describe(tokens, text)
        for key, attribute in statement['attrs'].items():
            if key not in ('FNAME', 'FMAPFN') and not (key == 'FILE' and statement['kind'] == 'CALL'):
                continue
            value = attribute['value']
            if engine.is_builtin_map(key, value):
                continue
            if len(value) < 2 or value[0] not in ('"', "'") or value[-1] != value[0]:
                raise ValueError('Computed dependency cannot be relocated: ' + value)
            name = value[1:-1]
            normalized = posixpath.normpath(name)
            if (not name or '\\' in name or any(c in name for c in '\r\n\x00')
                    or PurePosixPath(name).is_absolute() or normalized in ('.', '..')
                    or normalized.startswith('../') or normalized not in known_files):
                raise ValueError('Unsafe or missing dependency: ' + name)
            replacement = asset_prefix + '/' + normalized
            edits.append((attribute['value_start'], attribute['value_end'],
                          value[0] + replacement + value[0]))
            changes.append({'attribute': key, 'from': name, 'to': replacement})
    for start, end, value in sorted(edits, reverse=True):
        text = text[:start] + value + text[end:]
    return text, changes


def _workspace(source, output_parent):
    """Choose an owned temporary directory outside the source case tree."""
    candidates = (Path(tempfile.gettempdir()), Path(__file__).resolve().parent,
                  Path.cwd(), output_parent)
    for candidate in candidates:
        candidate = candidate.resolve()
        if candidate.is_relative_to(source.parent):
            continue
        try:
            return tempfile.TemporaryDirectory(prefix='.toOPALX-', dir=candidate)
        except OSError:
            continue
    raise ValueError('No writable staging directory outside the source case; use a dedicated input case directory')


def _fingerprint(path):
    """Hash generated assets without loading binary field maps into memory."""
    digest = hashlib.sha256()
    with path.open('rb') as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b''):
            digest.update(block)
    return digest.hexdigest()


def convert(mode, infile, outfile, **options):
    """Stage unchanged engine output, relocate dependencies and publish new files.

    The exact entry filename is created last, exclusively. Rollback removes
    only paths created by this invocation, including failures during writes.
    No existing destination is overwritten and no source file is modified.
    """
    engine = load_engine(mode)
    source = Path(infile).expanduser().resolve()
    requested = Path(outfile).expanduser().absolute()
    if requested.suffix.lower() != '.in' or any(c in requested.name for c in '\\"\'\r\n\x00'):
        raise ValueError('--outfile must be a portable filename ending in .in')
    parent = requested.parent.resolve()
    if not parent.is_dir():
        raise ValueError('Output parent directory must already exist')
    destination = parent / requested.name
    assets = parent / (destination.name + '.assets')
    report_path = parent / (destination.name + '.report.json')
    for path in (destination, assets, report_path):
        if path.exists() or path.is_symlink():
            raise FileExistsError('Output already exists: ' + str(path))
    with _workspace(source, parent) as work:
        bundle = Path(work) / 'candidate'
        if mode == 'opal':
            if options:
                raise ValueError('OPAL mode has no additional conversion controls')
            backend = engine.process(source, bundle, replace_unavailable=True)
            entry = bundle / source.name
        else:
            if {'force_no_space_charge', 'replace_unavailable'} & options.keys():
                raise ValueError('Element replacement and inactive fieldsolver policies are fixed by --mode')
            if mode == 'astra':
                backend = engine.convert(source, bundle, force_no_space_charge=True, **options)
            else:
                backend = engine.convert(source, bundle, replace_unavailable=True, **options)
            entry = bundle / 'converted.in'
        if backend.get('status') == 'unsupported':
            raise ConversionFailure('Unsupported input; no output published. Use --inspect for diagnostics.', backend)
        files, problems = load_engine('opal').collect(entry)
        if problems:
            raise ConversionFailure('Generated dependency bundle cannot be relocated: ' + '; '.join(problems), backend)
        known = {path.relative_to(bundle).as_posix() for path in files}
        rewritten, relocations = {}, []
        for path, parsed in files.items():
            if parsed:
                text, changes = relocate(path.read_text(encoding='utf-8'), assets.name, known)
                rewritten[path] = text.encode('utf-8')
                relocations.extend({'file': path.relative_to(bundle).as_posix(), **change} for change in changes)
        report = {'tool': 'toOPALX', 'version': VERSION, 'mode': mode,
                  'backend_version': _ENGINE_VERSIONS[mode], 'backend_source_sha256': _ENGINE_HASHES[mode],
                  'infile': str(source), 'outfile': str(destination), 'assets_directory': str(assets),
                  'report_file': str(report_path), 'status': backend['status'],
                  'physics_validated': False, 'backend_report': backend,
                  'working_directory': str(parent), 'relocations': relocations,
                  'entry_mapping': {'backend': entry.relative_to(bundle).as_posix(), 'published': destination.name},
                  'output_sha256': {}, **_policy_report(mode, backend)}
        owned_assets = owned_report = owned_entry = False
        try:
            assets.mkdir()
            owned_assets = True
            for path in sorted(bundle.rglob('*')):
                if path.is_dir() or path == entry:
                    continue
                if path.is_symlink() or not path.is_file():
                    raise ValueError('Generated output must contain ordinary files')
                target = assets / path.relative_to(bundle)
                target.parent.mkdir(parents=True, exist_ok=True)
                if path in rewritten:
                    with target.open('xb') as stream:
                        stream.write(rewritten[path])
                else:
                    with path.open('rb') as src, target.open('xb') as dst:
                        shutil.copyfileobj(src, dst)
                report['output_sha256'][str(target)] = _fingerprint(target)
            entry_bytes = rewritten[entry]
            report['output_sha256'][str(destination)] = hashlib.sha256(entry_bytes).hexdigest()
            with report_path.open('x', encoding='utf-8') as stream:
                owned_report = True
                json.dump(report, stream, indent=2, allow_nan=False)
                stream.write('\n')
            with destination.open('xb') as stream:
                owned_entry = True
                stream.write(entry_bytes)
        except Exception:
            if owned_entry:
                destination.unlink()
            if owned_report:
                report_path.unlink()
            if owned_assets:
                shutil.rmtree(assets)
            raise
    return report


def failure_summary(report):
    """Keep blocking causes visible without dumping a structured report."""
    blockers = []
    for message in report.get('dependency_problems', []):
        blockers.append(('', str(message)))
    for issue in report.get('issues', []):
        if isinstance(issue, str):
            blockers.append(('', issue))
        elif isinstance(issue, dict) and issue.get('severity', 'unsupported') == 'unsupported':
            blockers.append(('', str(issue.get('message', issue.get('code', 'Unsupported input')))))
    for file in report.get('files', []):
        for issue in file.get('issues', []):
            default = 'unsupported' if file.get('status') == 'unsupported' else 'review'
            if issue.get('severity', default) != 'unsupported':
                continue
            location = str(file.get('file', ''))
            if issue.get('line'):
                location += ':'+str(issue['line'])
            blockers.append((location, str(issue.get('message', issue.get('code', 'Unsupported input')))))
    grouped = {}
    for location, message in blockers:
        if message in grouped:
            grouped[message][1] += 1
        else:
            grouped[message] = [location, 1]
    lines = []
    for message, (location, count) in grouped.items():
        text = '  '+(location+': ' if location else '')+message
        if count > 1:
            text += ' ('+str(count)+' occurrences; first location shown)'
        lines.append(text)
    return '\n'.join(lines)


def main(argv=None):
    """Parse mode before help, then inspect or convert without running a tracker."""
    arguments = list(sys.argv[1:] if argv is None else argv)
    preliminary = argparse.ArgumentParser(add_help=False)
    preliminary.add_argument('--mode', choices=MODES)
    preliminary.add_argument('--more', action='store_true')
    selected, _ = preliminary.parse_known_args(arguments)
    parser = build_parser(selected.mode, more=selected.more)
    args = parser.parse_args(arguments)
    if args.more:
        parser.error('--more is only available with --help')
    if not args.inspect and args.outfile is None:
        parser.error('--outfile is required for conversion')
    if args.inspect and args.outfile is not None:
        parser.error('--inspect writes nothing; omit --outfile')
    options = {key: value for key, value in vars(args).items()
               if key not in ('mode', 'infile', 'outfile', 'inspect', 'more', 'json_output')}
    try:
        report = (inspect(args.mode, args.infile, **options) if args.inspect else
                  convert(args.mode, args.infile, args.outfile, **options))
        if args.json_output or args.inspect:
            print(json.dumps(report, indent=2, allow_nan=False), flush=True)
        else:
            print('Converted ('+report['status']+'): '+report['outfile']+'\n'
                  +'Report: '+report['report_file'], flush=True)
        if not args.inspect:
            print(conversion_summary(report), file=sys.stderr)
        else:
            for warning in report.get('placement_warnings', []):
                print(warning, file=sys.stderr)
        return 2 if report['status'] == 'unsupported' else 0
    except (OSError, UnicodeError, ValueError) as exc:
        print('toOPALX: ' + str(exc), file=sys.stderr)
        if isinstance(exc, ConversionFailure) and exc.report is not None:
            if args.json_output:
                print(json.dumps(exc.report, indent=2, allow_nan=False), file=sys.stderr)
            else:
                summary = failure_summary(exc.report)
                if summary:
                    print(summary, file=sys.stderr)
        return 2


