        "            assigned = s['tokens'][0][0].upper()\n"
        "        elif s['kind'] in ('REAL', 'BOOL', 'STRING') and len(s['tokens']) > 1:\n"
        "            assigned = s['tokens'][1][0].upper()\n"
        '        else:\n'
        '            continue\n'
        '        if assigned in names:\n'
        "            return 'Conditional distribution count identifier changes before BEAM: '+assigned\n"
        '    return None\n'
        '\n'
        '\n'
        'def check_run_controls(track, run, symbols, issue):\n'
        '    """Check locally provable turn/energy-stop constraints for one TRACK/RUN pair."""\n'
        "    ta, ra = track['attrs'], run['attrs']\n"
        "    line = symbols.get(reference_name(ta.get('LINE', {}).get('value', '')))\n"
        "    ring = line is not None and line['kind'] == 'RING'\n"
        "    turns = 'TURNS' in ra\n"
        "    ordinary = ra.get('SPECTRALTUNES', {}).get('value', 'FALSE').upper() == 'FALSE'\n"
        "    kinetic = 'EKINSTOP' in ta\n"
        '    if not turns and not kinetic:\n'
        '        return\n'
        '    if turns and (not ring or not ordinary):\n'
        "        issue('run-turns-context', 'Directed TURNS is a RING limit; verify LINE topology and tracking mode', run)\n"
        '    if kinetic and line and not ring:\n'
        "        issue('ekinstop-ring-required', 'EKINSTOP requires a RING with the single-container cyclotron-gap path', track, 'unsupported')\n"
        '    if kinetic and turns:\n'
        "        issue('ekinstop-turns-conflict', 'EKINSTOP cannot be combined with explicit RUN.TURNS', run, 'unsupported')\n"
        '    if (ring and turns and ordinary) or kinetic:\n'
        "        for key in ('DT', 'MAXSTEPS', 'ZSTOP'):\n"
        "            if key in ta and (array_arity(ta[key]['value']) or 0) > 1:\n"
        "                issue('stop-schedule-unsupported', 'Explicit ring TURNS/EKINSTOP requires one ' + key + ' segment', track, 'unsupported')\n"
        '        try:\n'
        '            names = track_beam_names(ta)\n'
        '        except InputError:\n'
        "            issue('stop-beam-review', 'Resolve beam selection before validating turn/energy stopping', track)\n"
        '        else:\n'
        '            if len(names) != 1:\n'
        "                issue('stop-multibeam-unsupported', 'Directed ring TURNS/EKINSTOP requires one selected beam', track, 'unsupported')\n"
        '\n'
        '\n'
        'def check_attribute_rules(s, symbols, issue, recognized):\n'
        '    """Recognize emission/beam/RF controls without evaluating OPAL expressions."""\n'
        "    k, a = s['kind'], s['attrs']\n"
        '    def note(rule, message):\n'
        "        recognized.append({'rule': rule, 'name': s['name']})\n"
        '        issue(rule, message, s)\n'
        "    if k == 'OPTION':\n"
        "        if 'REPARTFREQ' in a:\n"
        "            note('option-repartition-preserve', 'Repartition frequency retained; review load balance and changes to layout/reduction order and floating-point reproducibility')\n"
        "        if 'ENABLELINEARTRANSFERMAPS' in a:\n"
        "            note('option-transfermaps-preserve', 'First-order external-field maps during design-orbit threading retained; no tracking integrator or map-accuracy conversion')\n"
        "        if set(a) & {'ASCIIDUMP', 'EBDUMP', 'ECHO', 'INFO'}:\n"
        "            note('option-output-preserve', 'ASCII/field dumps and message controls retained; verify output availability and downstream analysis expectations')\n"
        "        if 'SEED' in a:\n"
        "            note('option-seed-preserve', 'Random seed expression retained; -1 requests a time-based seed, and fixed seeds alone do not ensure backend/MPI reproducibility')\n"
        "    if k == 'RUN':\n"
        "        if 'TURNS' in a:\n"
        "            note('run-turns-preserve', 'Directed RING turn limit retained; check positive integer count, single schedule/beam, fresh run and return-plane eligibility')\n"
        "        if 'SCFIELDUPDATE' in a:\n"
        "            note('run-self-field-preserve', 'MIDPOINT/PRESTEP self-field timing retained; PRESTEP is the historical OPAL ordering, no default or timing change inferred')\n"
        '            if a[\'SCFIELDUPDATE\'][\'value\'].strip(\'"\\\'\').upper() not in {\'MIDPOINT\', \'PRESTEP\'}:\n'
        "                issue('self-field-mode-unsupported', 'SCFIELDUPDATE must be MIDPOINT or PRESTEP in this target', s, 'unsupported')\n"
        "    if k == 'FIELDSOLVER' and 'RCUT' in a:\n"
        "        note('fieldsolver-cutoff-preserve', 'P3M RCUT [m] retained; target derives ALPHA=2/RCUT, review cutoff positivity, mesh/particle resolution and force accuracy')\n"
        '        if a.get(\'TYPE\', {}).get(\'value\', \'\').strip(\'"\\\'\').upper() != \'P3M\':\n'
        "            issue('fieldsolver-cutoff-context', 'RCUT belongs to P3M; verify selected solver before using this setting', s)\n"
        "    if k == 'BEAM' and 'POLARIZATION' in a:\n"
        "        note('beam-polarization-preserve', 'Rest-frame polarization vector in lab axes retained; even zero enables muon spin tracking, review magnitude and decay behavior')\n"
        "        arity = array_arity(a['POLARIZATION']['value'])\n"
        '        if arity not in (None, 0, 3):\n'
        "            issue('polarization-shape-unsupported', 'POLARIZATION must have three components (empty means unset)', s, 'unsupported')\n"
        "        if arity and reference_name(a.get('PARTICLE', {}).get('value', '')) != 'MUON':\n"
        "            issue('polarization-species-unsupported', 'Nonempty POLARIZATION requires explicit PARTICLE=MUON', s, 'unsupported')\n"
        "    if k == 'TRACK' and 'EKINSTOP' in a:\n"
        "        note('track-energy-stop-preserve', 'Kinetic energy stop [GeV] retained; requires positive threshold above launch energy, fresh single-container cyclotron RING, complete RF kick and no explicit TURNS')\n"
        "    if k == 'DISTRIBUTION':\n"
        '        if a.get(\'TYPE\', {}).get(\'value\', \'\').strip(\'"\\\'\').upper() == \'GAUSS\':\n'
        "            degenerate = [key for key in ('SIGMAX', 'SIGMAY', 'SIGMAZ')\n"
        "                          if key not in a or literal_zero(a[key]['value']) is True]\n"
        '            if degenerate:\n'
        "                issue('gauss-zero-width-target', 'Zero/default spatial widths retained: '\n"
        "                      + ', '.join(degenerate) + '; requires target Gaussian point-mass fix (older builds can produce NaN); no finite width is invented', s)\n"
        '        if set(a) & DIST_EMISSION:\n'
        "            note('distribution-emission-preserve', 'Emission flag, time profile and step controls preserved; review cathode versus injection, time units and type-specific scheduling')\n"
        '        if set(a) & DIST_SHAPE:\n'
        "            note('distribution-shape-preserve', 'Cutoffs/correlations preserved; check sigma normalization, longitudinal time/space convention and correlation ordering')\n"
        "    if k == 'EMISSIONSOURCE':\n"
        '        if set(a) & SOURCE_THERMAL:\n'
        "            note('source-thermal-preserve', 'EMISSIONMODEL and EKIN [eV] preserved; check thermal momentum versus source P0 and distribution eligibility')\n"
        '            model = a.get(\'EMISSIONMODEL\', {}).get(\'value\', \'NONE\').strip(\'"\\\'\').upper()\n'
        "            if model not in {'NONE', 'ASTRA'}:\n"
        "                issue('emission-model-unsupported', 'Only NONE and ASTRA are target emission models', s, 'unsupported')\n"
        "            dist = symbols.get(reference_name(a.get('DISTRIBUTION', {}).get('value', '')))\n"
        '            dist_type = dist[\'attrs\'].get(\'TYPE\', {}).get(\'value\', \'\').strip(\'"\\\'\').upper() if dist else \'\'\n'
        "            if model == 'ASTRA' and dist_type in {'GAUSS', 'UNIFORM', 'MULTIVARIATEGAUSS', 'FROMFILE', 'EMITTEDFROMFILE'}:\n"
        "                code = 'emittedfile-thermal-unsupported' if dist_type == 'EMITTEDFROMFILE' else 'thermal-distribution-unsupported'\n"
        "                issue(code, dist_type + ' requires EMISSIONMODEL=NONE; no thermal model is substituted', s, 'unsupported')\n"
        '        if set(a) & SOURCE_BOUNDARY:\n'
        "            note('source-boundary-preserve', 'Image/shifted-Green plane controls preserved; review OPEN solver eligibility, selected sources, single-plane constraints and dump/step counts')\n"
        "            zero = a.get('ZEROFACE_R0Z', {}).get('value', 'FALSE').upper()\n"
        "            shifted = a.get('SHIFTED_GREENS_FUNCTION', {}).get('value', 'FALSE').upper()\n"
        "            if zero == shifted == 'TRUE':\n"
        "                issue('source-boundary-conflict', 'ZEROFACE_R0Z and SHIFTED_GREENS_FUNCTION cannot both be true', s, 'unsupported')\n"
        "    if k == 'TRACK':\n"
        "        if 'SOURCES' in a:\n"
        "            note('track-sources-ignored', 'Target ignores TRACK.SOURCES; actual source lists must be attached to selected BEAM definitions')\n"
        "        if 'BEAMS' in a:\n"
        "            note('track-beams-preserve', 'BEAMS selection and order preserved; review primary reference beam, per-beam charge/sources and shared field evolution')\n"
        '            try:\n'
        '                names = track_beam_names(a)\n'
        '            except InputError as exc:\n'
        "                issue('track-beams-selection', str(exc), s, 'unsupported')\n"
        '            else:\n'
        '                for name in names:\n'
        "                    if name not in symbols or symbols[name]['kind'] != 'BEAM':\n"
        "                        issue('track-beams-reference', 'BEAMS member does not resolve to a local BEAM: ' + name, s)\n"
        '                if len(names) != len(set(names)):\n'
        "                    issue('track-beams-duplicate', 'Repeated beam names retained; verify repeated-container intent', s)\n"
        "                if 'BEAM' in a:\n"
        "                    issue('track-beams-precedence', 'Nonempty BEAMS overrides BEAM; an empty literal array falls back to BEAM', s)\n"
        "                if len(names) > 1 and 'INITIALORBIT' in a:\n"
        "                    issue('multibeam-initialorbit-unsupported', 'INITIALORBIT requires exactly one selected beam', s, 'unsupported')\n"
        '    if k == \'RFCAVITY\' and (set(a) & (RF_SINGLEGAP | RF_MODELS) or a.get(\'TYPE\', {}).get(\'value\', \'\').strip(\'"\\\'\').upper() == \'SINGLEGAP\'):\n'
        "        note('rf-singlegap-preserve', 'Single-gap controls preserved: RMIN/RMAX/GAPWIDTH [m], PHI0 [deg]; legacy nonzero literal ANGLE/PDIS with complete geometry are converted separately; remaining legacy controls require review')\n"
        '        typ = a.get(\'TYPE\', {}).get(\'value\', \'\').strip(\'"\\\'\').upper()\n'
        "        fmap = a.get('FMAPFN', {}).get('value', '')\n"
        '        if typ != \'SINGLEGAP\' or not fmap or fmap in (\'""\', "\'\'"):\n'
        "            issue('rf-singlegap-context', 'Native single-gap map controls require TYPE=SINGLEGAP and a nonempty FMAPFN; verify actual cavity mode', s)\n"
        '        else:\n'
        "            for key in ('ANGLE', 'PDIS', 'DVOLT', 'LAG', 'DLAG'):\n"
        "                if key in a and literal_zero(a[key]['value']) is not True:\n"
        "                    severity = 'unsupported' if literal_zero(a[key]['value']) is False else 'review'\n"
        "                    issue('rf-singlegap-static-conflict', key + ' must be zero for native map SINGLEGAP; symbolic values require review, no phase/pose rewrite inferred', s, severity)\n"
        '            for key in sorted(RF_MODELS & a.keys()):\n'
        '                if a[key][\'value\'] not in (\'""\', "\'\'"):\n'
        "                    issue('rf-singlegap-model-conflict', 'Native map SINGLEGAP requires empty ' + key + '; retained', s, 'unsupported')\n"
        '\n'
        '\n'
        'def convert_legacy_gap_poses(text):\n'
        '    """Convert explicit legacy SINGLEGAP geometry in the cyclotron-centred lab.\n'
        '\n'
        '    OPAL e01a0804714008cf287a078af9e829a4e5000c8b:\n'
        '    ParallelCyclotronTracker::checkGapCross uses D=x*sin(a)-y*cos(a)-d,\n'
        '    Dold>0 -> Dnew<=0. OpalCavity::update converts mm and degrees to SI.\n'
        '    With (x,y,z)_old -> (x,-z,y)_new, Ry(-a) has radial local x and\n'
        '    local z=-D. Origin is (d*sin(a),0,-d*cos(a)). No sector-frame shift\n'
        '    is included: magnetic sectors must share this cyclotron-centred lab.\n'
        '    Nonzero ANGLE/PDIS distinguish legacy geometry from native SI gaps.\n'
        '    Expressions are retained algebraically, never evaluated.\n'
        '    """\n'
        '    edits, records = [], []\n'
        '    for ts in statements(text):\n'
        '        stmt = describe(ts, text)\n'
        "        a = stmt['attrs']\n"
        "        if (stmt['kind'] != 'RFCAVITY'\n"
        '                or a.get(\'TYPE\', {}).get(\'value\', \'\').strip(\'"\\\'\').upper() != \'SINGLEGAP\'\n'
        '                or a.get(\'FMAPFN\', {}).get(\'value\', \'\') in (\'\', \'""\', "\'\'")\n'
        "                or not {'ANGLE', 'PDIS', 'RMIN', 'RMAX', 'GAPWIDTH'} <= a.keys()\n"
        "                or any(k in a for k in ('X', 'Y', 'Z', 'THETA', 'PHI', 'PSI', 'ELEMEDGE'))):\n"
        '            continue\n'
        "        raw = [a[k]['value'] for k in ('ANGLE', 'PDIS')]\n"
        '        if any(literal_zero(v) is None for v in raw) or all(literal_zero(v) for v in raw):\n'
        '            continue\n'
        "        angle, distance = [float(v.replace('D', 'e').replace('d', 'e')) for v in raw]\n"
        '        if not all(math.isfinite(v) for v in (angle, distance)):\n'
        '            continue\n'
        '        theta, d = -math.radians(angle), distance * 0.001\n'
        '        x, z = d * math.sin(-theta), -d * math.cos(-theta)\n'
        '        pose = dict(X=x, Y=0.0, Z=z, THETA=theta, PHI=0.0, PSI=0.0)\n'
        "        for key in ('ANGLE', 'PDIS'):\n"
        '            attr = a[key]\n'
        '            # Blank tokens only, preserving source comments and line numbers.\n'
        "            for token, start, end in tokenize(text[attr['start']:attr['end']]):\n"
        "                edits.append((attr['start']+start, attr['start']+end, ' '*(end-start)))\n"
        "        for key in ('RMIN', 'RMAX', 'GAPWIDTH'):\n"
        '            attr = a[key]\n'
        "            value = attr['value']\n"
        '            if literal_zero(value) is not None:\n'
        "                number = float(value.replace('D', 'e').replace('d', 'e')) * 0.001\n"
        "                replacement = format(number, '.17g') if math.isfinite(number) else '0.001*('+value+')'\n"
        '            else:\n'
        "                replacement = '0.001*('+value+')'\n"
        "            edits.append((attr['value_start'], attr['value_end'], replacement))\n"
        '        end = ts[-1][1]\n'
        "        edits.append((end, end, ', '+', '.join(k+'='+format(v, '.17g') for k, v in pose.items())))\n"
        "        records.append(dict(rule='legacy-singlegap-pose', name=stmt['name'], kind='RFCAVITY',\n"
        "                            line=text.count('\\n', 0, ts[0][1])+1, pose=pose,\n"
        "                            reason='Converted legacy ANGLE/PDIS to cyclotron-centred SI pose and gap dimensions mm to m; verify sector placement and positive radial branch'))\n"
        '    for start, end, replacement in sorted(edits, reverse=True):\n'
        '        text = text[:start]+replacement+text[end:]\n'
        '    return text, records\n'
        '\n'
        '\n'
        'def convert_legacy_cyclotrons(text, map_headers=None, reserved_names=()):\n'
        '    """Expand PSI RING maps about the cyclotron-centred lab origin.\n'
        '\n'
        '    The map determines Rm, not RINIT. At azimuth a the entrance is\n'
        '    (Rm*cos(a),0,Rm*sin(a)), Ry(-a). Hence local (-Rm,0,0) is\n'
        '    the common ring centre and local angular support tiles [a,a+2*pi/SYM).\n'
        '    Old OPAL folds theta modulo 360/SYMMETRY with zero map origin.\n'
        '    """\n'
        '    map_headers = map_headers or {}\n'
        '    declarations = [describe(ts, text) for ts in statements(text)]\n'
        '    used = {str(n).upper() for n in reserved_names}\n'
        "    used.update(d['name'].upper() for d in declarations if d['name'])\n"
        "    used.update(d['tokens'][1][0].upper() for d in declarations\n"
        "                if d['kind'] in ('REAL', 'BOOL', 'STRING') and len(d['tokens'])>1)\n"
        '    edits, records = [], []\n'
        "    allowed = {'TYPE', 'FMAPFN', 'SYMMETRY', 'BSCALE', 'CYHARMON', 'RFFREQ',\n"
        "               'RINIT', 'PHIINIT', 'PRINIT', 'ZINIT', 'PZINIT'}\n"
        '    for stmt in declarations:\n'
        "        if stmt['kind'] != 'CYCLOTRON':\n"
        '            continue\n'
        "        a, name = stmt['attrs'], stmt['name']\n"
        '        def fail(message):\n'
        "            raise InputError('CYCLOTRON '+str(name)+': '+message)\n"
        '        if not name or a.get(\'TYPE\', {}).get(\'value\', \'\').strip(\'"\\\'\').upper() != \'RING\':\n'
        "            fail('only named TYPE=RING PSI maps can be converted')\n"
        '        if set(a)-allowed:\n'
        "            fail('unconverted settings: '+', '.join(sorted(set(a)-allowed)))\n"
        "        symmetry = a.get('SYMMETRY', {}).get('value', '')\n"
        '        if literal_zero(symmetry) is None:\n'
        "            fail('SYMMETRY must be an explicit integer literal')\n"
        "        sym = float(symmetry.replace('D','e').replace('d','e'))\n"
        '        if not math.isfinite(sym) or not 2 <= sym <= 128 or sym != int(sym):\n'
        "            fail('SYMMETRY must be an integer between 2 and 128')\n"
        '        sym = int(sym)\n'
        "        fmap = a.get('FMAPFN', {}).get('value', '')\n"
        '        if len(fmap)<2 or fmap[0] not in (\'"\', "\'") or fmap[-1] != fmap[0]:\n'
        "            fail('FMAPFN must be a literal PSI map filename')\n"
        '        header = map_headers.get(fmap[1:-1])\n'
        '        if header is None:\n'
        "            fail('PSI map header is required to derive the sector reference radius')\n"
        '        try:\n'
        '            tokens = header.split()\n'
        '            rmin, dr, amin, da = map(float, tokens[:4])\n'
        '            nr, nt = int(tokens[17]), int(tokens[18])\n'
        '            if dr < 0: dr = -1/dr\n'
        '            if da < 0: da = -1/da\n'
        '            rmin, dr = rmin*0.001, dr*0.001\n'
        '            if (not all(math.isfinite(v) for v in (rmin,dr,amin,da))\n'
        '                    or not (rmin>0 and dr>0 and da>0 and 5<=nr<=100000 and 5<=nt<=100000)\n'
        '                    or nr*nt>100000000 or abs(math.radians(amin))>1e-12\n'
        '                    or abs(math.radians(nt*da)-2*math.pi/sym)>1e-8):\n'
        "                raise ValueError('incompatible grid')\n"
        '            radius = rmin+0.5*(nr-1)*dr\n'
        "            if not math.isfinite(radius): raise ValueError('invalid radius')\n"
        '        except (ValueError, IndexError, TypeError, OverflowError):\n'
        "            fail('invalid PSI map header or angular coverage does not match SYMMETRY')\n"
        "        names = [name+'_sector'+str(k) for k in range(sym)]\n"
        '        if any(n.upper() in used for n in names):\n'
        "            fail('generated sector name conflicts with an existing declaration')\n"
        '        used.update(n.upper() for n in names)\n'
        "        warning = ('WARNING: Generated CYCLOTRON sector placements need to be checked. '\n"
        "                   'Verify the cyclotron centre, map orientation, sector seams and RF placements; '\n"
        "                   'legacy initial conditions and RF timing require separate migration.')\n"
        "        poses, lines = [], ['// '+warning]\n"
        '        for k, sector in enumerate(names):\n'
        '            angle = 2*math.pi*k/sym\n'
        '            pose = dict(X=radius*math.cos(angle), Y=0.0, Z=radius*math.sin(angle),\n'
        '                        THETA=-angle, PHI=0.0, PSI=0.0)\n'
        '            poses.append(dict(name=sector, **pose))\n'
        "            attrs = ['FMAPFN='+fmap, 'SYM='+str(sym)]\n"
        "            if 'BSCALE' in a: attrs.append('BSCALE='+a['BSCALE']['value'])\n"
        "            attrs += [key+'='+format(value,'.17g') for key,value in pose.items()]\n"
        "            lines.append(sector+': CYCLOTRONSECTOR, '+', '.join(attrs)+';')\n"
        "        lines.append(name+': LINE=('+','.join(names)+');')\n"
        "        start,end = stmt['tokens'][0][1], stmt['tokens'][-1][2]\n"
        '        original = text[start:end]\n'
        "        lines += ['// Legacy declaration retained for review:']+['// '+line for line in original.splitlines()]\n"
        "        edits.append((start,end,'\\n'.join(lines)+'\\n'))\n"
        "        records.append(dict(rule='legacy-cyclotron-sectors', name=name, kind='CYCLOTRON',\n"
        "                            line=text.count('\\n',0,start)+1, reason=warning, sectors=poses,\n"
        '                            reference_radius_m=radius, map_header_checked=True,\n'
        "                            legacy_attributes={key: value['value'] for key,value in a.items()}))\n"
        '    for start,end,replacement in sorted(edits, reverse=True):\n'
        '        text = text[:start]+replacement+text[end:]\n'
        '    return text, records\n'
        '\n'
        '\n'
        'def migrate(text, *, map_headers=None, reserved_names=(), allow_zero_face_references=True):\n'
        '    """Apply guarded source/count rules and return candidate plus diagnostics."""\n'
        '    issues, changes, edits, recognized = [], [], [], []\n'
        "    def issue(code, message, stmt=None, severity='review'):\n"
        "        offset = stmt['tokens'][0][1] if stmt else 0\n"
        "        issues.append({'code': code, 'severity': severity,\n"
        "                       'line': text.count('\\n', 0, offset) + 1, 'message': message})\n"
        '    try:\n'
        '        text, syntax_changes = normalize_legacy_syntax(text)\n'
        '        text, removed = remove_obsolete(text)\n'
        '        text, approximations = approximate_binomial(text)\n'
        '        text, gap_poses = convert_legacy_gap_poses(text)\n'
        '        text, cyclotrons = convert_legacy_cyclotrons(text, map_headers, reserved_names)\n'
        '        leaves, controls = scan_statements(tokenize(text), InputError)\n'
        '        paths = branch_paths(len(leaves), controls)\n'
        "        stmts = [{**describe(t, text), 'branch_path': path} for t, path in zip(leaves, paths)]\n"
        '    except InputError as exc:\n'
        "        issue('parse', str(exc), severity='unsupported')\n"
        "        return text, {'status': 'unsupported', 'issues': issues, 'changes': [],\n"
        "                      'recognized_rules': [], 'constructs': {}, 'removed_constructs': [],\n"
        "                      'model_approximations': []}\n"
        '    for item in syntax_changes + gap_poses + cyclotrons:\n'
        '        changes.append(dict(item))\n'
        "        issues.append({'code': item['rule'], 'severity': 'review',\n"
        "                       'line': item['line'], 'message': item['reason']})\n"
        "        recognized.append({'rule': item['rule'], 'name': item.get('name')})\n"
        '    for item in removed:\n'
        '        changes.append(dict(item))\n'
        "        issues.append({'code': item['rule'], 'severity': 'review',\n"
        "                       'line': item['line'], 'message': item['reason']})\n"
        "        recognized.append({'rule': item['rule'], 'name': item['name']})\n"
        '    for item in approximations:\n'
        '        changes.append(dict(item))\n'
        "        issues.append({'code': item['rule'], 'severity': 'review',\n"
        "                       'line': item['line'], 'message': item['reason']})\n"
        "        recognized.append({'rule': item['rule'], 'name': item['name']})\n"
        '    for control in controls:\n'
        "        issues.append({'code': 'conditional-preserve', 'severity': 'review',\n"
        "                       'line': text.count('\\n', 0, control['start'])+1,\n"
        "                       'message': 'Native IF/ELSE and all branches retained; condition is not evaluated and may depend on target OPALVERSION'})\n"
        "        recognized.append({'rule': 'conditional-preserve', 'name': None})\n"
        '    symbols = {}\n'
        '    for s in stmts:\n'
        "        if s['name']:\n"
        "            key = s['name'].upper()\n"
        '            if key in symbols:\n'
        "                code = 'conditional-definition-ambiguous' if s['branch_path'] or symbols[key]['branch_path'] else 'duplicate-name'\n"
        "                issue(code, 'Repeated or branch-dependent definition requires explicit migration review: ' + key, s, 'unsupported')\n"
        '            symbols[key] = s\n'
