        '\n'
        '\n'
        'def dependencies(text):\n'
        '    """Find literal include/asset references without interpreting expressions."""\n'
        '    refs = []\n'
        '    for ts in statements(text):\n'
        '        s = describe(ts, text)\n'
        "        for key, a in s['attrs'].items():\n"
        "            if key in ('FNAME', 'FMAPFN') or (s['kind'] == 'CALL' and key == 'FILE'):\n"
        "                v = a['value']\n"
        '                if is_builtin_map(key, v):\n'
        '                    continue\n'
        '                literal = len(v) >= 2 and v[0] in (\'"\', "\'") and v[-1] == v[0]\n'
        "                refs.append((v[1:-1] if literal else v, s['kind'] == 'CALL', literal))\n"
        '    return refs\n'
        '\n'
        '\n'
        'def is_builtin_map(attribute, value):\n'
        '    """The exact native profile sentinel bypasses Fieldmap\'s filesystem access."""\n'
        '    return attribute == \'FMAPFN\' and value in (\'"1DPROFILE1-DEFAULT"\', "\'1DPROFILE1-DEFAULT\'")\n'
        '\n'
        '\n'
        'def collect(entry, *, texts=None, includes_only=False):\n'
        '    """Collect safe dependencies, optionally using rewritten input texts.\n'
        '\n'
        '    An include-only pass discovers lattice declarations before unavailable\n'
        '    elements are replaced; their discarded maps need not exist. The regular\n'
        '    pass then checks every dependency that the candidate still references.\n'
        '    """\n'
        '    entry = entry.resolve()\n'
        '    root = entry.parent\n'
        '    files, problems, active = {}, [], set()\n'
        '    def visit(path, parse):\n'
        '        if path.absolute() != path.resolve():\n'
        "            problems.append('Symlink dependency requires manual copying: ' + str(path))\n"
        '            return\n'
        '        path = path.resolve()\n'
        '        try:\n'
        '            path.relative_to(root)\n'
        '        except ValueError:\n'
        "            problems.append('Dependency escapes case directory: ' + str(path))\n"
        '            return\n'
        '        if path in active:\n'
        "            problems.append('Include cycle: ' + str(path))\n"
        '            return\n'
        '        if path in files and (files[path] or not parse):\n'
        '            return\n'
        '        if not path.is_file():\n'
        "            problems.append('Missing dependency: ' + str(path))\n"
        '            return\n'
        '        files[path] = parse\n'
        '        if parse:\n'
        '            active.add(path)\n'
        '            try:\n'
        "                text = texts[path] if texts is not None and path in texts else path.read_text(encoding='utf-8')\n"
        '                text, _ = normalize_legacy_syntax(text)\n'
        '                text, _ = remove_obsolete(text)\n'
        '                for name, include, literal in dependencies(text):\n'
        '                    if includes_only and not include:\n'
        '                        continue\n'
        "                    if not literal or '\\\\' in name or Path(name).is_absolute():\n"
        "                        problems.append('Nonportable or computed dependency: ' + name)\n"
        '                    else:\n'
        '                        # OPAL resolves CALL and asset paths from its working directory.\n'
        '                        visit(root / name, include)\n'
        '            except (InputError, UnicodeError) as exc:\n'
        "                problems.append(str(path) + ': ' + str(exc))\n"
        '            active.remove(path)\n'
        '    visit(entry, True)\n'
        '    return files, problems\n'
        '\n'
        '\n'
        'def drift_replacements(entry):\n'
        '    """Replace identifiable unavailable lattice declarations without evaluation.\n'
        '\n'
        '    Membership is discovered across literal includes, but source files and\n'
        '    their scalar expressions remain untouched. Only named unknown element\n'
        '    types used by LINE/RING, or explicitly excluded element types, qualify;\n'
        '    arbitrary commands and known non-element constructs remain strict errors.\n'
        '    """\n'
        '    entry = Path(entry).resolve()\n'
        '    files, problems = collect(entry, includes_only=True)\n'
        '    texts, parsed, members = {}, {}, set()\n'
        '    for path in files:\n'
        '        try:\n'
        "            text, _ = normalize_legacy_syntax(path.read_text(encoding='utf-8'))\n"
        '            text, _ = remove_obsolete(text)\n'
        '            declarations = [describe(tokens, text) for tokens in statements(text)]\n'
        '            for declaration in declarations:\n'
        "                if declaration['kind'] in ('LINE', 'RING'):\n"
        "                    names, _ = list_members(declaration['tokens'], declaration['kind'] == 'LINE')\n"
        '                    members.update(name.upper() for name in names)\n'
        '            texts[path], parsed[path] = text, declarations\n'
        '        except (InputError, UnicodeError) as exc:\n'
        "            problems.append(str(path) + ': ' + str(exc))\n"
        '    replacements, declared_names, duplicate_names = [], set(), set()\n'
        '    for declarations in parsed.values():\n'
        '        for declaration in declarations:\n'
        "            if declaration['name']:\n"
        "                name = declaration['name'].upper()\n"
        '                if name in declared_names:\n'
        '                    duplicate_names.add(name)\n'
        '                declared_names.add(name)\n'
        '    if duplicate_names:\n'
        "        problems.append('Duplicate source declaration names: ' + ', '.join(sorted(duplicate_names)))\n"
        '        return texts, replacements, problems\n'
        "    non_elements = set(SCHEMA) | {'REAL', 'BOOL', 'STRING', 'LINE', 'RING',\n"
        "        'EMISSIONSOURCELIST', 'VALUE', 'ENDTRACK', 'QUIT', 'STOP', 'SCALAR_ASSIGNMENT'}\n"
        "    keep = {'L', 'ELEMEDGE'} | set(PLACEMENT.split())\n"
        '    for path, declarations in parsed.items():\n'
        '        text, edits = texts[path], []\n'
        '        for declaration in declarations:\n'
        "            kind, name, attrs = declaration['kind'], declaration['name'], declaration['attrs']\n"
        "            if not name or kind in non_elements or kind == 'CYCLOTRON':\n"
        '                continue\n'
        '            if kind in REFUSED:\n'
        "                problems.append(name+': '+REFUSED[kind])\n"
        '                continue\n'
        '            # A source type can name an earlier element declaration. Resolving\n'
        '            # inheritance requires separate geometry/model rules; never label\n'
        '            # such an instance unavailable just because its base is not a type\n'
        '            # keyword. The normal migration diagnostics keep it unsupported.\n'
        '            if kind in declared_names:\n'
        '                continue\n'
        '            if kind not in UNAVAILABLE and name.upper() not in members:\n'
        '                continue\n'
        "            source_default = kind == 'SOURCE'\n"
        "            if source_default and set(attrs) != {'ELEMEDGE'}:\n"
        "                extras = ', '.join(sorted(set(attrs) - {'ELEMEDGE'})) or 'missing ELEMEDGE'\n"
        "                raise InputError(f'{name}: legacy SOURCE drift rule requires only ELEMEDGE; {extras} needs review')\n"
        "            if 'L' not in attrs and not source_default:\n"
        "                raise InputError(f'{name}: unavailable {kind} requires explicit L for drift replacement')\n"
        '            # The retired SOURCE used a fixed 5 cm field-free interval upstream\n'
        '            # of ELEMEDGE, unlike an ordinary downstream-placed element. This\n'
        '            # documented legacy default is not a general missing-length guess.\n'
        "            length = '0.05' if source_default else attrs['L']['value']\n"
        "            compact = re.sub(r'\\s+', '', length)\n"
        "            literal = re.fullmatch(r'\\(*([+-]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)(?:[eEdD][+-]?\\d+)?)\\)*', compact)\n"
        '            if literal:\n'
        "                number = float(literal.group(1).replace('d', 'e').replace('D', 'E'))\n"
        '                if not math.isfinite(number) or number < 0:\n'
        "                    raise InputError(f'{name}: drift replacement L must be finite and nonnegative')\n"
        "            elif (compact.upper().strip('()+-') in {'NAN', 'INF', 'INFINITY', 'TRUE', 'FALSE'}\n"
        '                  or any(token[0] in (\'{\', \'}\', \'[\', \']\') or token[0].startswith((\'"\', "\'"))\n'
        '                         for token in tokenize(length))):\n'
        "                raise InputError(f'{name}: drift replacement L must be a scalar length expression')\n"
        "            retained_values = {key: value['value'] for key, value in attrs.items() if key in keep}\n"
        '            if source_default:\n'
        "                retained_values = {'L': length, 'ELEMEDGE': '('+attrs['ELEMEDGE']['value']+')-0.05'}\n"
        "            retained = [key + '=' + value for key, value in retained_values.items()]\n"
        "            replacement = name + ': DRIFT, ' + ', '.join(retained) + ';'\n"
        "            start, end = declaration['tokens'][0][1], declaration['tokens'][-1][2]\n"
        '            edits.append((start, end, replacement))\n'
        "            record = {'name': name, 'source_type': kind, 'replacement_type': 'DRIFT',\n"
        "                'length': length, 'length_requires_review': literal is None,\n"
        "                'file': str(path.relative_to(entry.parent)), 'line': text.count('\\n', 0, start) + 1,\n"
        "                'reason': UNAVAILABLE.get(kind, kind + ' has no verified element conversion rule'),\n"
        "                'retained_attributes': retained_values}\n"
        '            if source_default:\n'
        "                record.update(length_origin='legacy-source-fixed-upstream-interval',\n"
        "                    reason='Legacy SOURCE fixed 0.05 m upstream interval preserved as DRIFT; backward-particle interception and loss output are omitted')\n"
        '            replacements.append(record)\n'
        '        for start, end, replacement in sorted(edits, reverse=True):\n'
        '            text = text[:start] + replacement + text[end:]\n'
        '        texts[path] = text\n'
        '    return texts, replacements, problems\n'
        '\n'
        '\n'
        "_NUMBER = re.compile(rb'[+-]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)(?:[eE][+-]?\\d+)?\\Z')\n"
        "_FORTRAN_NUMBER = re.compile(rb'[+-]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)[dD][+-]?\\d+\\Z')\n"
        "_INTEGER = re.compile(rb'[+-]?\\d+\\Z')\n"
        "_NONFINITE = {b'nan', b'+nan', b'-nan', b'inf', b'+inf', b'-inf',\n"
        "              b'infinity', b'+infinity', b'-infinity'}\n"
        "_HEADER = b'x px y py z pz'\n"
        "_COLUMNS = ('x', 'px', 'y', 'py', 'z', 'pz')\n"
        '\n'
        '\n'
        'def _numeric_like(token):\n'
        '    return bool(_NUMBER.fullmatch(token) or _FORTRAN_NUMBER.fullmatch(token)\n'
        '                or token.lower() in _NONFINITE)\n'
        '\n'
        '\n'
        'def _literal(value):\n'
        '    """Recognize a bare or quoted keyword; never evaluate an input expression."""\n'
        '    if isinstance(value, dict):\n'
        "        value = value.get('value')\n"
        '    if not isinstance(value, str):\n'
        '        return None\n'
        '    value = value.strip()\n'
        '    if len(value) >= 2 and value[0] in (\'"\', "\'") and value[-1] == value[0]:\n'
        '        value = value[1:-1]\n'
        '    return value.upper()\n'
        '\n'
        '\n'
        'def normalize_legacy_particles(raw, contexts):\n'
        '    """Return ``(candidate_bytes, migration_record_or_None, problem_or_None)``.\n'
        '\n'
        '    ``contexts`` contains all references to this asset. Each reference is either\n'
        "    an engine-shaped declaration ``{'attrs': {'TYPE': {'value': 'FROMFILE'},\n"
        "    ...}, ...}`` or a simple mapping ``{'TYPE': 'FROMFILE', ...}``. Attributes\n"
        '    must use their uppercase keys. The only safe context is literal FROMFILE\n'
        '    with INPUTMOUNITS absent/NONE and EMITTED absent/FALSE. No expression or\n'
        '    unknown context is resolved by this helper.\n'
        '\n'
        '    Recognized native headers and opaque/unrecognized assets pass through\n'
        '    without validation claims. Once an integer/numeric count plus numeric data\n'
        '    identifies a headerless candidate, malformed counts, rows, values or unsafe\n'
        '    contexts return a blocking problem and unchanged bytes. Bare count-only\n'
        '    files remain opaque. Complete six-column finite data is required; no rows,\n'
        '    units, values, comments or existing line endings are rewritten.\n'
        '    """\n'
        '    if not isinstance(raw, bytes):\n'
        "        raise TypeError('Particle asset must be bytes')\n"
        '    lines = raw.splitlines(keepends=True)\n'
        '    content = [(index, line.strip()) for index, line in enumerate(lines)\n'
        "               if line.strip() and not line.lstrip().startswith(b'#')]\n"
        '    if len(content) < 2:\n'
        '        return raw, None, None\n'
        '    count_index, count_line = content[0]\n'
        "    data_tokens = content[1][1].split(b'#', 1)[0].split()\n"
        '    header_names = {token.lower() for token in data_tokens}\n'
        '    # Native headers may contain additional columns or use a different order.\n'
        "    if set(_COLUMNS).issubset({name.decode('ascii', errors='replace') for name in header_names}):\n"
        '        return raw, None, None\n'
        '    looks_numeric = bool(data_tokens) and (\n'
        '        _numeric_like(data_tokens[0])\n'
        '        or (len(data_tokens) == 6 and sum(_numeric_like(token) for token in data_tokens) >= 5))\n'
        '    if not looks_numeric:\n'
        '        return raw, None, None\n'
        '    # A text/map asset beginning with a word is not a legacy particle file.\n'
        '    if not (_INTEGER.fullmatch(count_line) or _numeric_like(count_line)\n'
        "            or _INTEGER.fullmatch(count_line.split(b'#', 1)[0].strip())):\n"
        '        return raw, None, None\n'
        '\n'
        '    def refuse(message):\n'
        "        return raw, None, 'Legacy FROMFILE particle data: '+message\n"
        '\n'
        '    if not _INTEGER.fullmatch(count_line):\n'
        "        return refuse('the count line must be one positive integer without an inline comment')\n"
        '    try:\n'
        '        count = int(count_line)\n'
        '    except ValueError:\n'
        "        return refuse('the count is too large to interpret safely')\n"
        '    if count <= 0:\n'
        "        return refuse('the particle count must be positive')\n"
        '    records = content[1:]\n'
        '    if len(records) != count:\n'
        "        return refuse('declared count '+str(count)+' does not match '+str(len(records))+' data rows')\n"
        '    for line_index, line in records:\n'
        "        tokens = line.split(b'#', 1)[0].split()\n"
        '        if len(tokens) != 6:\n'
        "            return refuse('line '+str(line_index+1)+' must contain exactly six numeric columns')\n"
        '        for token in tokens:\n'
        '            if not _NUMBER.fullmatch(token):\n'
        "                return refuse('line '+str(line_index+1)+' contains a non-finite or unsupported numeric token')\n"
        '            try:\n'
        '                finite = math.isfinite(float(token))\n'
        '            except (ValueError, OverflowError):\n'
        '                finite = False\n'
        '            if not finite:\n'
        "                return refuse('line '+str(line_index+1)+' contains a non-finite numeric value')\n"
        '    if not isinstance(contexts, (list, tuple)) or not contexts:\n'
        "        return refuse('no verified FROMFILE reference context was supplied')\n"
        '    for context in contexts:\n'
        '        if not isinstance(context, dict):\n'
        "            return refuse('an asset reference context is not a declaration')\n"
        "        attrs = context.get('attrs', context)\n"
        "        if not isinstance(attrs, dict) or _literal(attrs.get('TYPE')) != 'FROMFILE':\n"
        "            return refuse('every asset reference must be literal TYPE=FROMFILE')\n"
        "        if 'INPUTMOUNITS' in attrs and _literal(attrs['INPUTMOUNITS']) != 'NONE':\n"
        "            return refuse('INPUTMOUNITS must be absent or literal NONE; no momentum rescaling is inferred')\n"
        "        if 'EMITTED' in attrs and _literal(attrs['EMITTED']) != 'FALSE':\n"
        "            return refuse('EMITTED must be absent or literal FALSE; emission-time data needs a separate rule')\n"
        '    count_raw = lines[count_index]\n'
        "    if count_raw.endswith(b'\\r\\n'):\n"
        "        newline = b'\\r\\n'\n"
        "    elif count_raw.endswith(b'\\n'):\n"
        "        newline = b'\\n'\n"
        '    else:\n'
        "        return refuse('count and data must use LF or CRLF line boundaries')\n"
        '    insertion = sum(len(line) for line in lines[:count_index+1])\n'
        '    candidate = raw[:insertion]+_HEADER+newline+raw[insertion:]\n'
        '    record = {\n'
        "        'rule': 'legacy-particle-header',\n"
        "        'source_sha256': hashlib.sha256(raw).hexdigest(),\n"
        "        'output_sha256': hashlib.sha256(candidate).hexdigest(),\n"
        "        'particle_count': count,\n"
        "        'columns': list(_COLUMNS),\n"
        "        'header_line': count_index+2,\n"
        "        'momentum_rescaled': False,\n"
        "        'reason': 'Inserted native FROMFILE column names in legacy x px y py z pz order; particle records, values and units are unchanged, with no rescaling',\n"
        '    }\n'
        '    return candidate, record, None\n'
        '\n'
        '\n'
        'def migrate_particle_assets(entry, payload, reports):\n'
        '    """Normalize verified legacy particle assets, preserving original sources.\n'
        '\n'
        '    Only literal distribution references qualify. Every use of a shared asset\n'
        '    is checked so a map, include, or different source model is never silently\n'
        '    interpreted as the legacy six-column nonemitted FROMFILE format.\n'
        '    """\n'
        '    uses, migrations, problems = {}, [], []\n'
        "    parsed_files = {report['file'] for report in reports}\n"
        '    for report in reports:\n'
        '        try:\n'
        "            text = payload[report['file']].decode('utf-8')\n"
        '            for tokens in statements(text):\n'
        '                statement = describe(tokens, text)\n'
        "                for key, attr in statement['attrs'].items():\n"
        "                    if key not in ('FNAME', 'FMAPFN') and not (key == 'FILE' and statement['kind'] == 'CALL'):\n"
        '                        continue\n'
        "                    value = attr['value']\n"
        '                    if is_builtin_map(key, value):\n'
        '                        continue\n'
        '                    if len(value) < 2 or value[0] not in (\'"\', "\'") or value[-1] != value[0]:\n'
        '                        continue\n'
        '                    target = (entry.parent/value[1:-1]).resolve()\n'
        '                    if not target.is_relative_to(entry.parent):\n'
        '                        continue\n'
        '                    rel = str(target.relative_to(entry.parent))\n'
        '                    uses.setdefault(rel, []).append({\n'
        "                        'kind': statement['kind'], 'attribute': key,\n"
        "                        'attrs': statement['attrs'], 'name': statement['name'],\n"
        "                        'file': report['file'], 'line': text.count('\\n', 0, tokens[0][1])+1})\n"
        '        except (UnicodeError, InputError):\n'
        '            # Existing file diagnostics retain the parse/encoding failure.\n'
        '            continue\n'
        "    by_name = {report['file']: report for report in reports}\n"
        '    for rel, contexts in sorted(uses.items()):\n'
        '        if rel not in payload or rel in parsed_files:\n'
        '            continue\n'
        "        if not any(context['kind'] == 'DISTRIBUTION' and context['attribute'] == 'FNAME'\n"
        "                   and reference_name(context['attrs'].get('TYPE', {}).get('value', ''))\n"
        "                   in ('FROMFILE', 'EMITTEDFROMFILE') for context in contexts):\n"
        '            continue\n'
        "        if any(context['kind'] != 'DISTRIBUTION' or context['attribute'] != 'FNAME'\n"
        '               for context in contexts):\n'
        "            problems.append(rel+': shared particle asset is also used by a map, include or non-distribution construct; no header rewrite performed')\n"
        '            continue\n'
        '        normalized, record, problem = normalize_legacy_particles(payload[rel], contexts)\n'
        '        if problem:\n'
        "            problems.append(rel+': '+problem)\n"
        '        if record is not None:\n'
        '            payload[rel] = normalized\n'
        "            record = {**record, 'file': rel}\n"
        '            migrations.append(record)\n'
        '            for context in contexts:\n'
        "                result = by_name[context['file']]\n"
        "                result['changes'].append(dict(record))\n"
        "                result['recognized_rules'].append({'rule': record['rule'], 'name': context['name']})\n"
        "                result['issues'].append({'code': record['rule'], 'severity': 'review',\n"
        "                                         'line': context['line'], 'message': rel+': '+record['reason']})\n"
        "                if result['status'] == 'converted':\n"
        "                    result['status'] = 'review-required'\n"
        '    return migrations, problems\n'
        '\n'
        '\n'
        'def process(entry, output=None, *, replace_unavailable=False):\n'
        '    """Inspect one dependency bundle, optionally writing into a fresh directory."""\n'
        '    entry = entry.resolve()\n'
        '    if not isinstance(replace_unavailable, bool):\n'
        "        raise InputError('Drift replacement flag must be logical')\n"
        '    if not entry.is_file():\n'
        "        raise InputError('Input does not exist: ' + str(entry))\n"
        '    if output is not None and (output.exists() or output.resolve().is_relative_to(entry.parent)):\n'
        "        raise InputError('Output must be new and outside the source case directory')\n"
        '    try:\n'
        '        texts, replacements, prior_problems = drift_replacements(entry) if replace_unavailable else ({}, [], [])\n'
        '    except InputError as exc:\n'
        '        texts, replacements, prior_problems = {}, [], [str(exc)]\n'
        '    files, problems = collect(entry, texts=texts)\n'
        '    problems = list(dict.fromkeys(prior_problems + problems))\n'
        '    # Use only dependencies already checked by collect; never open arbitrary map paths.\n'
        '    map_headers, reserved_names = {}, set()\n'
        '    for asset, parsed in files.items():\n'
        '        if not parsed:\n'
        "            with asset.open('rb') as stream:\n"
        "                map_headers[str(asset.relative_to(entry.parent))] = stream.read(65536).decode('ascii', errors='replace')\n"
        '        else:\n'
        '            try:\n'
        "                source_text = texts[asset] if asset in texts else asset.read_text(encoding='utf-8')\n"
        '                for ts in statements(source_text):\n'
        '                    declaration = describe(ts, source_text)\n'
        "                    if declaration['name']: reserved_names.add(declaration['name'].upper())\n"
        "                    elif declaration['kind'] in ('REAL', 'BOOL', 'STRING') and len(ts)>1:\n"
        '                        reserved_names.add(ts[1][0].upper())\n'
        '            except (InputError, UnicodeError):\n'
        '                pass  # Normal migration reports the parse error.\n'
        '    reports, payload, removed_constructs, model_approximations = [], {}, [], []\n'
        '    for path, parse in sorted(files.items()):\n'
        '        rel = str(path.relative_to(entry.parent))\n'
        '        raw = path.read_bytes()\n'
        '        if parse:\n'
        '            try:\n'
        "                original = raw.decode('utf-8')\n"
        '                try:\n'
        '                    filtered, syntax_changes = normalize_legacy_syntax(original)\n'
        '                    filtered, removed = remove_obsolete(filtered)\n'
        '                except InputError:\n'
        '                    filtered, removed, syntax_changes = original, [], []\n'
        '                candidate, result = migrate(texts.get(path, filtered), map_headers=map_headers,\n'
        '                    reserved_names=reserved_names, allow_zero_face_references=sum(files.values()) == 1)\n'
        "                result['model_approximations'] = [{**item, 'file': rel}\n"
        "                                                 for item in result['model_approximations']]\n"
        "                model_approximations.extend(result['model_approximations'])\n"
        "                result['removed_constructs'] = [{**item, 'file': rel} for item in removed]\n"
        "                removed_constructs.extend(result['removed_constructs'])\n"
        '                for item in syntax_changes + removed:\n'
        "                    result['changes'].append(dict(item))\n"
        "                    result['issues'].append({'code': item['rule'], 'severity': 'review',\n"
        "                                            'line': item['line'], 'message': item['reason']})\n"
        "                    result['recognized_rules'].append({'rule': item['rule'], 'name': item['name']})\n"
        "                    if result['status'] == 'converted':\n"
        "                        result['status'] = 'review-required'\n"
        '                for replacement in replacements:\n'
        "                    if replacement['file'] == rel:\n"
        "                        result['changes'].append({'rule': 'unavailable-element-drift', **replacement})\n"
        "                        result['issues'].append({'code': 'unavailable-element-drift', 'severity': 'review',\n"
        "                            'line': replacement['line'], 'message': replacement['name'] + ': ' +\n"
        "                            replacement['source_type'] + ' replaced with DRIFT; ' + replacement['reason']})\n"
        "                        if result['status'] == 'converted':\n"
        "                            result['status'] = 'review-required'\n"
        "                payload[rel] = candidate.encode('utf-8')\n"
        "                result['diff'] = ''.join(difflib.unified_diff(original.splitlines(True), candidate.splitlines(True), fromfile=rel, tofile=rel + ' (OPALX candidate)'))\n"
        '            except UnicodeError:\n'
        "                result = {'status': 'unsupported', 'issues': [{'code': 'encoding', 'message': 'UTF-8 input required'}], 'changes': [], 'constructs': {}, 'removed_constructs': [], 'model_approximations': []}\n"
        '                payload[rel] = raw\n'
        '            result.update(file=rel, sha256=hashlib.sha256(raw).hexdigest())\n'
        '            reports.append(result)\n'
        '        else:\n'
        '            payload[rel] = raw\n'
        '    asset_migrations, asset_problems = migrate_particle_assets(entry, payload, reports)\n'
        '    problems.extend(asset_problems)\n'
        '    # Cross-file symbols are intentionally not flattened into local scope.\n'
        "    status = 'unsupported' if problems or any(r['status'] == 'unsupported' for r in reports) else ('review-required' if any(r['status'] == 'review-required' for r in reports) else 'converted')\n"
        "    report = {'tool_version': VERSION, 'ruleset': RULESET, 'input': str(entry),\n"
        "              'status': status, 'physics_validated': False, 'dependency_problems': problems,\n"
        "              'unavailable_elements': replacements,\n"
        "              'removed_constructs': removed_constructs,\n"
        "              'model_approximations': model_approximations,\n"
        "              'asset_migrations': asset_migrations,\n"
        "              'files': reports, 'assets': sorted(set(payload) - {r['file'] for r in reports})}\n"
        '    if output is not None:\n'
        '        # Own metadata namespace avoids collisions with source assets.\n'
        "        if any(Path(p).parts[0] == '_opal2opalx' for p in payload):\n"
        "            raise InputError('Input uses reserved metadata directory _opal2opalx')\n"
        '        output.mkdir(parents=True, exist_ok=False)\n'
        '        for rel, raw in payload.items():\n'
        '            target = output / rel\n'
        '            target.parent.mkdir(parents=True, exist_ok=True)\n'
        '            target.write_bytes(raw)\n'
        "        meta = output / '_opal2opalx'\n"
        '        meta.mkdir()\n'
        "        (meta / 'report.json').write_text(json.dumps(report, indent=2) + '\\n', encoding='utf-8')\n"
        "        (meta / 'changes.diff').write_text(''.join(r.get('diff', '') for r in reports), encoding='utf-8')\n"
        '    return report\n'
        '\n'
        '\n'
        'def validate(entry, executable, output, timeout=60.0, allow_review=False):\n'
        '    """Run one copied case directly (one rank); execution is not physics validation."""\n'
        '    executable = executable.resolve()\n'
        '    if not executable.is_file():\n'
        "        raise InputError('OPALX executable not found; supply an existing installation with --opalx')\n"
        '    if not math.isfinite(timeout) or timeout <= 0:\n'
        "        raise InputError('Timeout must be positive')\n"
        '    inspection = process(entry)\n'
        "    prior = entry.resolve().parent / '_opal2opalx' / 'report.json'\n"
        '    if prior.is_file():\n'
        '        try:\n'
        "            prior_status = json.loads(prior.read_text(encoding='utf-8'))['status']\n"
        '        except (ValueError, KeyError) as exc:\n'
        "            raise InputError('Invalid prior conversion report') from exc\n"
        "        if prior_status != 'converted':\n"
        "            inspection['status'] = prior_status\n"
        "    if inspection['status'] != 'converted' and not allow_review:\n"
        "        raise InputError('Case requires review; inspect it first, or explicitly use --allow-review')\n"
        '    root = entry.resolve().parent\n'
        '    if output.exists() or output.resolve().is_relative_to(root):\n'
        "        raise InputError('Validation output must be new and outside the case directory')\n"
        "    if any(p.is_symlink() for p in root.rglob('*')):\n"
        "        raise InputError('Validation copy must not contain symlinks')\n"
        "    work = output / 'work'\n"
        '    shutil.copytree(root, work)\n'
        '    command = [str(executable), entry.name]\n'
        '    timed_out = False\n'
        "    with (output / 'stdout.log').open('wb') as stdout, (output / 'stderr.log').open('wb') as stderr:\n"
        '        try:\n'
        '            completed = subprocess.run(command, cwd=work, stdout=stdout, stderr=stderr,\n'
        '                                       timeout=timeout, check=False)\n'
        '            code = completed.returncode\n'
        '        except subprocess.TimeoutExpired:\n'
        '            timed_out, code = True, None\n'
        "    result = {'tool_version': VERSION, 'command': command, 'returncode': code,\n"
        "              'timed_out': timed_out, 'execution_passed': code == 0,\n"
        "              'physics_validated': False, 'inspection_status': inspection['status'],\n"
        "              'mode': 'direct single-rank execution; no numerical metric comparison'}\n"
        "    (output / 'validation.json').write_text(json.dumps(result, indent=2) + '\\n', encoding='utf-8')\n"
        '    return result\n'
        '\n'
        '\n'
        'def main(argv=None):\n'
        '    """CLI: exit 0 supported, 1 review/unsupported, 2 setup/I/O error."""\n'
        '    parser = argparse.ArgumentParser(description=__doc__)\n'
        "    parser.add_argument('--version', action='version', version=VERSION)\n"
        "    sub = parser.add_subparsers(dest='command', required=True)\n"
        "    for command in ('inspect', 'inventory', 'convert', 'batch'):\n"
        '        p = sub.add_parser(command)\n'
        "        p.add_argument('input', type=Path)\n"
        "        if command in ('convert', 'batch'):\n"
        "            p.add_argument('--output', type=Path, required=True)\n"
        "        p.add_argument('--report', type=Path, help='New JSON report path (never overwrite)')\n"
        "    p = sub.add_parser('validate', help='Optional isolated single-rank execution check')\n"
        "    p.add_argument('input', type=Path, help='Converted entry .in file')\n"
        "    p.add_argument('--opalx', type=Path, required=True)\n"
        "    p.add_argument('--output', type=Path, required=True)\n"
        "    p.add_argument('--timeout', type=float, default=60.0)\n"
        "    p.add_argument('--allow-review', action='store_true')\n"
        '    args = parser.parse_args(argv)\n'
        '    try:\n'
        "        if args.command == 'validate':\n"
        '            result = validate(args.input, args.opalx, args.output, args.timeout, args.allow_review)\n'
        '            print(json.dumps(result, indent=2))\n'
        "            return int(not result['execution_passed'])\n"
        '        if args.report and args.report.exists():\n'
        "            raise InputError('Report already exists')\n"
        "        if args.command in ('batch', 'inventory'):\n"
        '            root = args.input.resolve()\n'
        '            if not root.is_dir():\n'
        "                raise InputError('Batch input must be a directory')\n"
        "            if args.command == 'batch' and (args.output.exists() or args.output.resolve().is_relative_to(root)):\n"
        "                raise InputError('Batch output must be new and outside input tree')\n"
        "            entries = sorted(root.rglob('*.in'))\n"
        '            if not entries:\n'
        "                raise InputError('No .in files found')\n"
        "            reports = [process(p, args.output / p.relative_to(root).with_suffix('.in.opalx') if args.command == 'batch' else None) for p in entries]\n"
        '        else:\n'
        "            reports = [process(args.input, args.output if args.command == 'convert' else None)]\n"
        "        result = {'tool_version': VERSION, 'ruleset': RULESET,\n"
        "                  'summary': dict(sorted(Counter(r['status'] for r in reports).items())), 'cases': reports}\n"
        "        rendered = json.dumps(result, indent=2) + '\\n'\n"
        '        if args.report:\n'
        "            with args.report.open('x', encoding='utf-8') as f:\n"
        '                f.write(rendered)\n'
        "        print(rendered, end='')\n"
        '        for report in reports:\n'
        "            for file in report.get('files', []):\n"
        "                for change in file.get('changes', []):\n"
        "                    if change.get('rule') == 'legacy-cyclotron-sectors':\n"
        "                        print(change['reason'], file=sys.stderr)\n"
        "        return int(any(r['status'] != 'converted' for r in reports))\n"
        '    except (OSError, InputError) as exc:\n'
        "        print('opal2opalx: ' + str(exc), file=sys.stderr)\n"
